    /**
     * Tests getting all CartItems.
     *
     * @return    Collection
     */
    public List<CartItem> testGetAll() throws Throwable {
    LOGGER.info( "CartItemTest:testGetAll() - Retrieving Collection of CartItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CartItem : " );
    List<CartItem> collection  = null;

    try {
        // call the static get method on the CartItemService
        collection = service.getAllCartItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CartItem currEntity  = null;
            Iterator<CartItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCartItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

